public with sharing class ExchangeRateClient {

    public class ExchangeRateException extends Exception {}

    private static final String ENDPOINT = 'callout:FB_Exchange_Rates/v1/latest';
    private static final Pattern CODE_PATTERN = Pattern.compile('^[A-Z]{3}$');

    public static Map<String, Decimal> getRates(String baseCurrency, Set<String> quoteCurrencies) {
        // ---- Validation (no callout before this passes) ----
        String base = normalise(baseCurrency);
        if (base == null) {
            throw new ExchangeRateException('Invalid base currency code: ' + baseCurrency);
        }
        if (quoteCurrencies == null || quoteCurrencies.isEmpty()) {
            throw new ExchangeRateException('At least one quote currency is required.');
        }

        Set<String> quotes = new Set<String>();
        for (String q : quoteCurrencies) {
            String n = normalise(q);
            if (n == null) {
                throw new ExchangeRateException('Invalid quote currency code: ' + q);
            }
            quotes.add(n);
        }

        List<String> sortedQuotes = new List<String>(quotes);
        sortedQuotes.sort();

        // ---- Build request ----
        // Codes are validated as A-Z only, so no URL encoding is needed (commas stay literal).
        String url = ENDPOINT + '?base=' + base + '&symbols=' + String.join(sortedQuotes, ',');

        HttpResponse res = send(url);
        if (res.getStatusCode() == 503) {
            res = send(url); // single retry with an identical request
        }

        if (res.getStatusCode() != 200) {
            throw new ExchangeRateException(
                'Exchange rate request failed with HTTP status ' + res.getStatusCode()
            );
        }

        return parse(res.getBody(), quotes);
    }

    private static String normalise(String code) {
        if (code == null) {
            return null;
        }
        String c = code.trim().toUpperCase();
        return CODE_PATTERN.matcher(c).matches() ? c : null;
    }

    private static HttpResponse send(String url) {
        HttpRequest req = new HttpRequest();
        req.setEndpoint(url);
        req.setMethod('GET');
        req.setHeader('Accept', 'application/json');
        try {
            return new Http().send(req);
        } catch (CalloutException e) {
            throw new ExchangeRateException('Exchange rate callout failed: ' + e.getMessage());
        }
    }

    private static Map<String, Decimal> parse(String body, Set<String> quotes) {
        Map<String, Object> ratesRaw;
        try {
            Object parsed = JSON.deserializeUntyped(body);
            Map<String, Object> root = (Map<String, Object>) parsed;
            Object ratesObj = root.get('rates');
            if (ratesObj == null) {
                throw new ExchangeRateException('Response does not contain rates.');
            }
            ratesRaw = (Map<String, Object>) ratesObj;
        } catch (ExchangeRateException e) {
            throw e;
        } catch (Exception e) {
            throw new ExchangeRateException('Unable to parse exchange rate response: ' + e.getMessage());
        }

        Map<String, Object> upperRates = new Map<String, Object>();
        for (String k : ratesRaw.keySet()) {
            if (k != null) {
                upperRates.put(k.trim().toUpperCase(), ratesRaw.get(k));
            }
        }

        Map<String, Decimal> result = new Map<String, Decimal>();
        for (String q : quotes) {
            Object v = upperRates.get(q);
            Decimal rate;
            if (v instanceof Decimal) {
                rate = (Decimal) v;
            } else if (v instanceof Integer) {
                rate = Decimal.valueOf((Integer) v);
            } else if (v instanceof Long) {
                rate = Decimal.valueOf((Long) v);
            } else if (v instanceof Double) {
                rate = Decimal.valueOf((Double) v);
            } else {
                throw new ExchangeRateException('No rate returned for currency ' + q);
            }
            result.put(q, rate);
        }
        return result;
    }
}
