public with sharing class ContactDomainService {

    /**
     * Groups the contacts of the given accounts by lower-cased email domain.
     * Contacts without a usable email address are omitted.
     * Runs in user mode, so the running user's sharing, CRUD and FLS are enforced.
     */
    public static Map<String, List<Contact>> groupByEmailDomain(Set<Id> accountIds) {
        Map<String, List<Contact>> contactsByDomain = new Map<String, List<Contact>>();

        if (accountIds == null || accountIds.isEmpty()) {
            return contactsByDomain;
        }

        for (Contact c : [
            SELECT Id, Email, AccountId
            FROM Contact
            WHERE AccountId IN :accountIds
            AND Email != NULL
            WITH USER_MODE
        ]) {
            String domain = extractDomain(c.Email);
            if (String.isBlank(domain)) {
                continue;
            }
            List<Contact> bucket = contactsByDomain.get(domain);
            if (bucket == null) {
                bucket = new List<Contact>();
                contactsByDomain.put(domain, bucket);
            }
            bucket.add(c);
        }

        return contactsByDomain;
    }

    private static String extractDomain(String email) {
        if (String.isBlank(email)) {
            return null;
        }
        String trimmed = email.trim();
        Integer atIndex = trimmed.lastIndexOf('@');
        if (atIndex < 0 || atIndex == trimmed.length() - 1) {
            return null;
        }
        String domain = trimmed.substring(atIndex + 1).trim();
        return String.isBlank(domain) ? null : domain.toLowerCase('en_US');
    }
}
