public with sharing class RecordSearchService {

    public class SearchException extends Exception {}

    private static final Integer MAX_ALLOWED_ROWS = 200;

    public static List<SObject> search(
        String objectApiName,
        List<String> fields,
        Map<String, Object> filters,
        String orderByField,
        Integer maxRows
    ) {
        try {
            // ---- Validate simple inputs
            if (String.isBlank(objectApiName)) {
                throw new SearchException('An object API name is required.');
            }
            if (fields == null || fields.isEmpty()) {
                throw new SearchException('At least one field must be requested.');
            }
            if (maxRows == null || maxRows < 1 || maxRows > MAX_ALLOWED_ROWS) {
                throw new SearchException('maxRows must be between 1 and ' + MAX_ALLOWED_ROWS + '.');
            }

            // ---- Resolve object
            Schema.SObjectType sot = Schema.getGlobalDescribe().get(objectApiName.trim());
            if (sot == null) {
                throw new SearchException('Unknown object: ' + objectApiName);
            }
            Schema.DescribeSObjectResult objDescribe = sot.getDescribe();
            if (!objDescribe.isAccessible() || !objDescribe.isQueryable()) {
                throw new SearchException('You do not have access to read the object ' + objDescribe.getName() + '.');
            }
            Map<String, Schema.SObjectField> fieldMap = objDescribe.fields.getMap();

            // ---- Select fields (deduplicated, canonical names)
            List<String> selectFields = new List<String>{ 'Id' };
            Set<String> seen = new Set<String>{ 'id' };
            for (String f : fields) {
                Schema.DescribeFieldResult fd = resolveField(fieldMap, f, objDescribe.getName());
                if (!fd.isAccessible()) {
                    throw new SearchException('You do not have access to read the field ' + fd.getName() + '.');
                }
                String canonical = fd.getName();
                if (seen.add(canonical.toLowerCase())) {
                    selectFields.add(canonical);
                }
            }

            // ---- WHERE clause with bind variables
            List<String> conditions = new List<String>();
            Map<String, Object> binds = new Map<String, Object>();
            if (filters != null && !filters.isEmpty()) {
                Integer i = 0;
                for (String key : filters.keySet()) {
                    Schema.DescribeFieldResult fd = resolveField(fieldMap, key, objDescribe.getName());
                    if (!fd.isAccessible()) {
                        throw new SearchException('You do not have access to read the field ' + fd.getName() + '.');
                    }
                    if (!fd.isFilterable()) {
                        throw new SearchException('The field ' + fd.getName() + ' cannot be filtered.');
                    }
                    String bindName = 'bindVal' + i;
                    conditions.add(fd.getName() + ' = :' + bindName);
                    binds.put(bindName, filters.get(key));
                    i++;
                }
            }

            // ---- ORDER BY
            String orderClause = '';
            if (!String.isBlank(orderByField)) {
                Schema.DescribeFieldResult fd = resolveField(fieldMap, orderByField, objDescribe.getName());
                if (!fd.isAccessible()) {
                    throw new SearchException('You do not have access to read the field ' + fd.getName() + '.');
                }
                if (!fd.isSortable()) {
                    throw new SearchException('The field ' + fd.getName() + ' cannot be sorted.');
                }
                orderClause = ' ORDER BY ' + fd.getName() + ' ASC';
            }

            // ---- Build and run query
            String soql = 'SELECT ' + String.join(selectFields, ', ') + ' FROM ' + objDescribe.getName();
            if (!conditions.isEmpty()) {
                soql += ' WHERE ' + String.join(conditions, ' AND ');
            }
            soql += orderClause;
            soql += ' LIMIT ' + String.valueOf(maxRows);

            return Database.queryWithBinds(soql, binds, AccessLevel.USER_MODE);
        } catch (SearchException e) {
            throw e;
        } catch (Exception e) {
            SearchException se = new SearchException('Search failed: ' + e.getMessage());
            se.initCause(e);
            throw se;
        }
    }

    private static Schema.DescribeFieldResult resolveField(
        Map<String, Schema.SObjectField> fieldMap,
        String name,
        String objectName
    ) {
        if (String.isBlank(name)) {
            throw new SearchException('A blank field name was supplied.');
        }
        Schema.SObjectField f = fieldMap.get(name.trim());
        if (f == null) {
            throw new SearchException('Unknown field ' + name + ' on object ' + objectName + '.');
        }
        return f.getDescribe();
    }
}
