public with sharing class ContactLookupAction {

    public class Request {
        @InvocableVariable(label='Email' description='Email address to search for' required=true)
        public String email;
    }

    public class Result {
        @InvocableVariable(label='Contact Id' description='Id of the earliest created matching contact')
        public Id contactId;

        @InvocableVariable(label='Found' description='True if a matching contact was found')
        public Boolean found = false;
    }

    @InvocableMethod(
        label='Find Contact by Email'
        description='Finds the earliest created contact matching each email address (case-insensitive).'
    )
    public static List<Result> find(List<Request> requests) {
        List<Result> results = new List<Result>();
        if (requests == null || requests.isEmpty()) {
            return results;
        }

        // Normalize each request's email once
        List<String> normalized = new List<String>();
        Set<String> searchEmails = new Set<String>();
        for (Request req : requests) {
            String key = normalize(req == null ? null : req.email);
            normalized.add(key);
            if (key != null) {
                searchEmails.add(key);
            }
        }

        // One SOQL query per call; earliest created contact first
        Map<String, Id> contactIdByEmail = new Map<String, Id>();
        if (!searchEmails.isEmpty()) {
            for (Contact c : [
                SELECT Id, Email
                FROM Contact
                WHERE Email IN :searchEmails
                WITH USER_MODE
                ORDER BY CreatedDate ASC, Id ASC
            ]) {
                if (c.Email == null) {
                    continue;
                }
                String key = c.Email.trim().toLowerCase();
                if (!contactIdByEmail.containsKey(key)) {
                    contactIdByEmail.put(key, c.Id);
                }
            }
        }

        // One result per request, same order
        for (String key : normalized) {
            Result res = new Result();
            if (key != null && contactIdByEmail.containsKey(key)) {
                res.contactId = contactIdByEmail.get(key);
                res.found = true;
            } else {
                res.contactId = null;
                res.found = false;
            }
            results.add(res);
        }
        return results;
    }

    private static String normalize(String email) {
        if (String.isBlank(email)) {
            return null;
        }
        String trimmed = email.trim().toLowerCase();
        return String.isBlank(trimmed) ? null : trimmed;
    }
}
