public with sharing class OrderPayloadParser {

    public class PayloadException extends Exception {}

    public class Order {
        public String orderNumber;
        public Date orderDate;
        public String currencyCode;
        public String customerEmail;
        public List<Line> lines;
        public Decimal total;
    }

    public class Line {
        public String sku;
        public Integer quantity;
        public Decimal unitPrice;
        public Decimal discount;
        public Decimal lineTotal;
    }

    public static Order parse(String body) {
        if (String.isBlank(body)) {
            throw new PayloadException('Request body is empty.');
        }
        try {
            return doParse(body);
        } catch (PayloadException e) {
            throw e;
        } catch (Exception e) {
            throw new PayloadException('Invalid order payload: ' + e.getMessage());
        }
    }

    public static String toAcknowledgement(Order order) {
        if (order == null) {
            throw new PayloadException('Order is required.');
        }
        Map<String, Object> ack = new Map<String, Object>();
        ack.put('number', order.orderNumber);
        ack.put('status', 'RECEIVED');
        ack.put('lineCount', order.lines == null ? 0 : order.lines.size());
        ack.put('total', order.total == null ? 0 : order.total);
        return JSON.serialize(ack);
    }

    // ---------------------------------------------------------------

    private static Order doParse(String body) {
        Object parsed;
        try {
            parsed = JSON.deserializeUntyped(body);
        } catch (Exception e) {
            throw new PayloadException('Body is not valid JSON.');
        }
        if (!(parsed instanceof Map<String, Object>)) {
            throw new PayloadException('Body must be a JSON object.');
        }
        Map<String, Object> root = (Map<String, Object>) parsed;

        Order result = new Order();

        // number
        Object numberVal = root.get('number');
        if (numberVal instanceof String) {
            String n = ((String) numberVal).trim();
            if (String.isBlank(n)) {
                throw new PayloadException('Order number is required.');
            }
            result.orderNumber = n;
        } else if (isNumber(numberVal)) {
            result.orderNumber = String.valueOf(numberVal);
        } else {
            throw new PayloadException('Order number is required.');
        }

        // date
        Object dateVal = root.get('date');
        if (dateVal != null) {
            if (!(dateVal instanceof String)) {
                throw new PayloadException('Order date must be a string in yyyy-MM-dd format.');
            }
            String ds = ((String) dateVal).trim();
            if (ds.length() > 0) {
                result.orderDate = parseDate(ds);
            }
        }

        // currency
        Object curVal = root.get('currency');
        if (curVal instanceof String) {
            result.currencyCode = (String) curVal;
        }

        // customer
        Object custVal = root.get('customer');
        if (custVal instanceof Map<String, Object>) {
            Object emailVal = ((Map<String, Object>) custVal).get('email');
            if (emailVal instanceof String) {
                result.customerEmail = (String) emailVal;
            }
        }

        // lines
        result.lines = new List<Line>();
        Decimal total = 0;
        Object linesVal = root.get('lines');
        if (linesVal != null) {
            if (!(linesVal instanceof List<Object>)) {
                throw new PayloadException('Lines must be an array.');
            }
            for (Object item : (List<Object>) linesVal) {
                if (!(item instanceof Map<String, Object>)) {
                    throw new PayloadException('Each line must be a JSON object.');
                }
                Line l = parseLine((Map<String, Object>) item);
                result.lines.add(l);
                total += l.lineTotal;
            }
        }
        result.total = total.setScale(2, RoundingMode.HALF_UP);
        return result;
    }

    private static Line parseLine(Map<String, Object> raw) {
        Line l = new Line();

        Object skuVal = raw.get('sku');
        if (!(skuVal instanceof String) || String.isBlank((String) skuVal)) {
            throw new PayloadException('Line sku is required.');
        }
        l.sku = (String) skuVal;

        Object qtyVal = raw.get('quantity');
        if (!isNumber(qtyVal)) {
            throw new PayloadException('Line quantity is required and must be a number.');
        }
        Decimal qty = toDecimal(qtyVal);
        if (qty <= 0) {
            throw new PayloadException('Line quantity must be positive.');
        }
        if (qty != qty.setScale(0, RoundingMode.DOWN) || qty > 2147483647) {
            throw new PayloadException('Line quantity must be a whole number.');
        }
        l.quantity = qty.intValue();

        Object priceVal = raw.get('unitPrice');
        if (!isNumber(priceVal)) {
            throw new PayloadException('Line unitPrice is required and must be a number.');
        }
        Decimal price = toDecimal(priceVal);
        if (price < 0) {
            throw new PayloadException('Line unitPrice must not be negative.');
        }
        l.unitPrice = price;

        Object discVal = raw.get('discount');
        if (discVal == null) {
            l.discount = 0;
        } else if (isNumber(discVal)) {
            Decimal d = toDecimal(discVal);
            if (d < 0 || d > 1) {
                throw new PayloadException('Line discount must be between 0 and 1.');
            }
            l.discount = d;
        } else {
            throw new PayloadException('Line discount must be a number.');
        }

        l.lineTotal = (qty * price * (1 - l.discount)).setScale(2, RoundingMode.HALF_UP);
        return l;
    }

    private static Boolean isNumber(Object o) {
        return o instanceof Integer || o instanceof Long
            || o instanceof Decimal || o instanceof Double;
    }

    private static Decimal toDecimal(Object o) {
        if (o instanceof Decimal) {
            return (Decimal) o;
        }
        return Decimal.valueOf(String.valueOf(o));
    }

    private static Date parseDate(String s) {
        Pattern p = Pattern.compile('^(\\d{4})-(\\d{2})-(\\d{2})$');
        Matcher m = p.matcher(s);
        if (!m.matches()) {
            throw new PayloadException('Order date must be in yyyy-MM-dd format.');
        }
        Integer y = Integer.valueOf(m.group(1));
        Integer mo = Integer.valueOf(m.group(2));
        Integer d = Integer.valueOf(m.group(3));
        if (mo < 1 || mo > 12 || d < 1 || d > Date.daysInMonth(y, mo)) {
            throw new PayloadException('Order date is not a valid date.');
        }
        return Date.newInstance(y, mo, d);
    }
