public with sharing class ShipmentEventPublisher {

    public class Shipment {
        public String orderNumber;
        public String trackingNumber;
        public String carrier;

        public Shipment(String orderNumber, String trackingNumber, String carrier) {
            this.orderNumber = orderNumber;
            this.trackingNumber = trackingNumber;
            this.carrier = carrier;
        }
    }

    /**
     * Publishes one FB_Shipment_Event__e per shipment (skipping null shipments and
     * shipments with a blank order number) using a single EventBus.publish call.
     * Returns the number of events published successfully.
     */
    public static Integer publishShipments(List<ShipmentEventPublisher.Shipment> shipments) {
        if (shipments == null || shipments.isEmpty()) {
            return 0;
        }

        List<FB_Shipment_Event__e> events = new List<FB_Shipment_Event__e>();
        for (ShipmentEventPublisher.Shipment s : shipments) {
            if (s == null || String.isBlank(s.orderNumber)) {
                continue;
            }
            events.add(new FB_Shipment_Event__e(
                Order_Number__c = s.orderNumber,
                Tracking_Number__c = s.trackingNumber,
                Carrier__c = s.carrier
            ));
        }

        if (events.isEmpty()) {
            return 0;
        }

        List<Database.SaveResult> results = EventBus.publish(events);
        Integer successCount = 0;
        for (Database.SaveResult sr : results) {
            if (sr.isSuccess()) {
                successCount++;
            } else {
                for (Database.Error err : sr.getErrors()) {
                    System.debug(LoggingLevel.ERROR,
                        'Shipment event publish failed: ' + err.getStatusCode() + ' - ' + err.getMessage());
                }
            }
        }
        return successCount;
    }
}
