public with sharing class ErpAccountSyncJob implements Queueable {

    private final Set<Id> accountIds;
    private final Integer attempt;

    public ErpAccountSyncJob(Set<Id> accountIds, Integer attempt) {
        this.accountIds = accountIds == null ? new Set<Id>() : new Set<Id>(accountIds);
        this.attempt = attempt == null ? 1 : attempt;
    }

    public void execute(QueueableContext context) {
        // Attach the finalizer before doing any work so it runs even if the work fails.
        System.attachFinalizer(new ErpSyncFinalizer(accountIds, attempt));

        if (accountIds.isEmpty()) {
            return;
        }

        List<Account> accounts = [
            SELECT Id, Description
            FROM Account
            WHERE Id IN :accountIds
            WITH USER_MODE
        ];

        for (Account acc : accounts) {
            acc.Description = 'Synced to ERP';
        }

        // Plain DML is all-or-nothing; any failure throws an uncaught exception,
        // so the job fails and none of its changes are kept.
        update as user accounts;
    }
}
