public with sharing class ErpSyncFinalizer implements Finalizer {

    private static final String JOB_NAME = 'ErpAccountSyncJob';
    private static final Integer MAX_ATTEMPTS = 3;
    private static final Integer ERROR_MAX_LENGTH = 255;

    private final Set<Id> accountIds;
    private final Integer attempt;

    public ErpSyncFinalizer(Set<Id> accountIds, Integer attempt) {
        this.accountIds = accountIds == null ? new Set<Id>() : new Set<Id>(accountIds);
        this.attempt = attempt == null ? 1 : attempt;
    }

    public void execute(FinalizerContext context) {
        FB_Job_Log__c logEntry = new FB_Job_Log__c(
            Job_Name__c = JOB_NAME,
            Attempt__c = attempt
        );

        Boolean failed = context.getResult() != ParentJobResult.SUCCESS;

        if (failed) {
            logEntry.Status__c = 'Failed';
            Exception ex = context.getException();
            if (ex != null && ex.getMessage() != null) {
                logEntry.Error__c = ex.getMessage().left(ERROR_MAX_LENGTH);
            }
        } else {
            logEntry.Status__c = 'Success';
        }

        // Log infrastructure writes run in system mode so logging never depends on user permissions.
        insert logEntry;

        if (failed && attempt < MAX_ATTEMPTS) {
            System.enqueueJob(new ErpAccountSyncJob(accountIds, attempt + 1));
        }
    }
}
