public with sharing class OpportunityRollupService {

    /**
     * Returns, for each requested account Id, the sum of Amount over its won
     * opportunities whose CloseDate falls in the current calendar year.
     * Every requested Id is a key; accounts with nothing qualifying map to 0.
     */
    public static Map<Id, Decimal> wonAmountThisYear(Set<Id> accountIds) {
        Map<Id, Decimal> result = new Map<Id, Decimal>();

        if (accountIds == null || accountIds.isEmpty()) {
            return result;
        }

        // Seed every requested Id with 0 (ignore null entries in the set)
        Set<Id> queryIds = new Set<Id>();
        for (Id accId : accountIds) {
            if (accId != null) {
                result.put(accId, 0);
                queryIds.add(accId);
            }
        }

        if (queryIds.isEmpty()) {
            return result;
        }

        for (AggregateResult ar : [
            SELECT AccountId acctId, SUM(Amount) total
            FROM Opportunity
            WHERE AccountId IN :queryIds
              AND IsWon = true
              AND CloseDate = THIS_YEAR
            GROUP BY AccountId
            WITH USER_MODE
        ]) {
            Id acctId = (Id) ar.get('acctId');
            Decimal total = (Decimal) ar.get('total');
            if (acctId != null && result.containsKey(acctId)) {
                result.put(acctId, total == null ? 0 : total);
            }
        }

        return result;
    }
}
