    private static List<Opportunity> captureRenewals(Integer expectedCount) {
        fflib_ArgumentCaptor captor = fflib_ArgumentCaptor.forClass(SObject.class);
        ((fflib_ISObjectUnitOfWork) mocks.verify(uowMock, mocks.times(expectedCount)))
            .registerNew((SObject) captor.capture());
        List<Opportunity> result = new List<Opportunity>();
        for (Object value : captor.getAllValues()) {
