        fflib_ArgumentCaptor fieldCaptor = fflib_ArgumentCaptor.forClass(Schema.SObjectField.class);
        fflib_ArgumentCaptor relatedCaptor = fflib_ArgumentCaptor.forClass(SObject.class);
        ((fflib_ISObjectUnitOfWork) mocks.verify(uowMock, mocks.times(expectedCount)))
            .registerNew(
                (SObject) taskCaptor.capture(),
                (Schema.SObjectField) fieldCaptor.capture(),
                (SObject) relatedCaptor.capture()
            );
        RegisteredTasks result = new RegisteredTasks();
        for (Object value : taskCaptor.getAllValues()) {
            System.assert(value instanceof Task, 'Relationship registration is used for tasks');
            result.tasks.add((Task) value);
        }
        for (Object value : fieldCaptor.getAllValues()) {
            result.fields.add((Schema.SObjectField) value);
        }
        for (Object value : relatedCaptor.getAllValues()) {
            result.related.add((SObject) value);
        }
        return result;
    }

    private static void verifyNothingRegisteredOrCommitted() {
