        setupMocks(ids, opps);

        Test.startTest();
        Integer result = OpportunityCleanupService.closeStale(ids, CUTOFF);
        Test.stopTest();

        Assert.areEqual(2, result, 'Only the two stale open opportunities should be closed');

        fflib_ArgumentCaptor captor = fflib_ArgumentCaptor.forClass(SObject.class);
        ((fflib_ISObjectUnitOfWork) mocks.verify(uowMock, 2)).registerDirty((SObject) captor.capture());
        List<Object> registered = captor.getAllValues();
        Assert.areEqual(2, registered.size());

        Set<Id> registeredIds = new Set<Id>();
        for (Object o : registered) {
            Opportunity opp = (Opportunity) o;
            registeredIds.add(opp.Id);
            Assert.areEqual('Closed Lost', opp.StageName, 'Registered opportunity must be Closed Lost');
            Assert.areEqual(
                OpportunityCleanupService.LOST_REASON,
                opp.Description,
