    }

    public Accounts(List<SObject> records) {
        super(records, Schema.Account.SObjectType);
    }

    public override Schema.SObjectType getSObjectType() {
        return Schema.Account.SObjectType;
    }

    public override Object getType() {
        return Schema.Account.SObjectType;
    }

    public List<Account> getAccounts() {
        List<Account> result = new List<Account>();
        for (SObject record : getRecords()) {
            result.add((Account) record);
        }
        return result;
    }

    public IAccounts selectByRating(String rating) {
        List<Account> matching = new List<Account>();
        for (Account acc : getAccounts()) {
            if (acc.Rating == rating) {
                matching.add(acc);
            }
        }
        return (IAccounts) Application.Domain.newInstance(
            (List<SObject>) matching,
            Account.SObjectType
        );
    }

    public Set<Id> getOwnerIds() {
        Set<Id> ownerIds = new Set<Id>();
        for (Account acc : getAccounts()) {
            if (acc.OwnerId != null) {
                ownerIds.add(acc.OwnerId);
            }
        }
        return ownerIds;
    }

    public void setRating(String rating) {
        for (Account acc : getAccounts()) {
            acc.Rating = rating;
        }
    }

    public class Constructor implements fflib_IDomainConstructor {
        public fflib_IDomain construct(List<Object> objectList) {
            List<SObject> records = new List<SObject>();
            for (Object obj : objectList) {
                records.add((SObject) obj);
            }
            return (fflib_IDomain) new Accounts(records);
        }
    }
