public with sharing class OpportunityWinService {

    private static final String STAGE_CLOSED_WON = 'Closed Won';

    public static Integer markWon(Set<Id> opportunityIds) {
        if (opportunityIds == null || opportunityIds.isEmpty()) {
            return 0;
        }

        fflib_ISObjectUnitOfWork uow = Application.UnitOfWork.newInstance();
        Integer closedCount = 0;

        for (Opportunity opp : OpportunitiesSelector.newInstance().selectById(opportunityIds)) {
            if (opp.StageName == STAGE_CLOSED_WON) {
                continue;
            }

            opp.StageName = STAGE_CLOSED_WON;
            opp.CloseDate = Date.today();
            uow.registerDirty(opp);

            // Published by the unit of work only after the commit succeeded
            uow.registerPublishAfterSuccessTransaction(
                new Deal_Won__e(
                    Opportunity_Id__c = String.valueOf(opp.Id),
                    Amount__c = opp.Amount
                )
            );
            closedCount++;
        }

        if (closedCount == 0) {
            return 0;
        }

        // Single commit; any DML exception propagates and no events are published
        uow.commitWork();

        return closedCount;
    }
}
