public with sharing class ContactPhoneCleanup {

    /**
     * Strips every character that is not a digit or '+' from Contact.Phone.
     * Contacts without a phone are ignored.
     * Returns a map of Contact Id -> first error message for each contact that could not be saved.
     */
    public static Map<Id, String> normalizePhones(List<Id> contactIds) {
        Map<Id, String> failures = new Map<Id, String>();

        if (contactIds == null || contactIds.isEmpty()) {
            return failures;
        }

        // One query for all contacts (a Set avoids duplicate-Id issues in the update list)
        List<Contact> contacts = [
            SELECT Id, Phone
            FROM Contact
            WHERE Id IN :new Set<Id>(contactIds)
            AND Phone != null
        ];

        for (Contact c : contacts) {
            if (String.isNotBlank(c.Phone)) {
                c.Phone = c.Phone.replaceAll('[^0-9+]', '');
            }
        }

        if (contacts.isEmpty()) {
            return failures;
        }

        // Single DML after the loop; partial success allowed
        List<Database.SaveResult> results = Database.update(contacts, false);

        // Results are returned in the same order as the input list
        for (Integer i = 0; i < results.size(); i++) {
            Database.SaveResult sr = results[i];
            if (!sr.isSuccess()) {
                List<Database.Error> errors = sr.getErrors();
                failures.put(
                    contacts[i].Id,
                    errors.isEmpty() ? 'Unknown error' : errors[0].getMessage()
                );
            }
        }

        return failures;
    }
}
