            Boolean relevantChange =
                opp.StageName != oldOpp.StageName ||
                opp.Amount != oldOpp.Amount ||
                opp.AccountId != oldOpp.AccountId;
            if (relevantChange) {
                if (opp.AccountId != null) {
                    accountIds.add(opp.AccountId);
                }
                // Opportunity moved: the previous account needs recalculating too
                if (oldOpp.AccountId != null) {
                    accountIds.add(oldOpp.AccountId);
                }
            }
        }
    }

    if (!accountIds.isEmpty()) {
        AccountRatingService.recalculateAsync(accountIds);
    }
}
