public without sharing class AccountRatingService {

    @TestVisible
    private static final Decimal HOT_THRESHOLD = 100000;

    /**
     * Entry point for callers (e.g. the trigger). Uses a single @future call for
     * the whole set of accounts. Future calls are not allowed from batch or
     * future context, so in those cases the work is done synchronously.
     */
    public static void recalculateAsync(Set<Id> accountIds) {
        if (accountIds == null || accountIds.isEmpty()) {
            return;
        }
        if (System.isFuture() || System.isBatch()) {
            calculateAndUpdate(accountIds);
        } else {
            recalculate(accountIds);
        }
    }

    @future
    public static void recalculate(Set<Id> accountIds) {
        calculateAndUpdate(accountIds);
    }

    private static void calculateAndUpdate(Set<Id> accountIds) {
        if (accountIds == null || accountIds.isEmpty()) {
            return;
        }

        // Open opportunity count and largest open amount per account
        Map<Id, Integer> openCount = new Map<Id, Integer>();
        Map<Id, Decimal> maxAmount = new Map<Id, Decimal>();

        for (AggregateResult ar : [
            SELECT AccountId acc, COUNT(Id) cnt, MAX(Amount) maxAmt
            FROM Opportunity
            WHERE AccountId IN :accountIds AND IsClosed = false
            GROUP BY AccountId
        ]) {
            Id accId = (Id) ar.get('acc');
            openCount.put(accId, (Integer) ar.get('cnt'));
            maxAmount.put(accId, (Decimal) ar.get('maxAmt'));
        }

        List<Account> toUpdate = new List<Account>();
        for (Account acc : [SELECT Id, Rating FROM Account WHERE Id IN :accountIds]) {
            String newRating = 'Cold';
            Integer cnt = openCount.get(acc.Id);
            if (cnt != null && cnt > 0) {
                Decimal maxAmt = maxAmount.get(acc.Id);
                newRating = (maxAmt != null && maxAmt >= HOT_THRESHOLD) ? 'Hot' : 'Warm';
            }
            if (acc.Rating != newRating) {
                toUpdate.add(new Account(Id = acc.Id, Rating = newRating));
            }
        }

        if (!toUpdate.isEmpty()) {
            List<Database.SaveResult> results = Database.update(toUpdate, false);
            for (Integer i = 0; i < results.size(); i++) {
                if (!results[i].isSuccess()) {
                    System.debug(LoggingLevel.ERROR,
                        'AccountRatingService failed for Account ' + toUpdate[i].Id + ': ' +
                        results[i].getErrors()[0].getMessage());
                }
            }
        }
    }
}
