public with sharing class CaseSurveyJob implements Queueable {

    private final List<Id> caseIds;

    public CaseSurveyJob(List<Id> caseIds) {
        this.caseIds = caseIds;
    }

    public void execute(QueueableContext context) {
        if (caseIds == null || caseIds.isEmpty()) {
            return;
        }

        // Re-query for current state; skip cases that were reopened or lost their contact.
        List<Case> cases = [
            SELECT Id, CaseNumber, ContactId
            FROM Case
            WHERE Id IN :caseIds
            AND IsClosed = true
            AND ContactId != null
        ];

        Date dueDate = Date.today().addDays(2);
        List<Task> tasks = new List<Task>();
        List<Id> taskCaseIds = new List<Id>();

        for (Case c : cases) {
            tasks.add(new Task(
                WhatId = c.Id,
                WhoId = c.ContactId,
                Subject = 'CSAT survey: ' + c.CaseNumber,
                ActivityDate = dueDate,
                Status = 'Not Started'
            ));
            taskCaseIds.add(c.Id);
        }

        if (tasks.isEmpty()) {
            return;
        }

        // Partial success: one failing record must not block the others.
        List<Database.SaveResult> results = Database.insert(tasks, false);
        for (Integer i = 0; i < results.size(); i++) {
            if (!results[i].isSuccess()) {
                for (Database.Error err : results[i].getErrors()) {
                    System.debug(LoggingLevel.ERROR,
                        'CaseSurveyJob: failed to create survey task for case '
                        + taskCaseIds[i] + ': ' + err.getStatusCode() + ' - ' + err.getMessage());
                }
            }
        }

        // Vendor integration will be added here; wrap each case's call in its own
        // try/catch so one failure doesn't affect the others.
    }
}
