public with sharing class RenewalReminderService {

    /**
     * Emails the owner of each given opportunity a renewal reminder.
     * Uses a single Messaging.sendEmail call (limit: 10 invocations per transaction)
     * with allOrNothing = false so one failing email does not block the others.
     *
     * @return number of emails that were sent successfully
     */
    public static Integer sendReminders(List<Id> opportunityIds) {
        if (opportunityIds == null || opportunityIds.isEmpty()) {
            return 0;
        }

        Set<Id> uniqueIds = new Set<Id>(opportunityIds);
        uniqueIds.remove(null);
        if (uniqueIds.isEmpty()) {
            return 0;
        }

        List<Opportunity> opportunities = [
            SELECT Id, Name, CloseDate, OwnerId, Owner.Name
            FROM Opportunity
            WHERE Id IN :uniqueIds
            WITH USER_MODE
        ];

        List<Messaging.SingleEmailMessage> messages = new List<Messaging.SingleEmailMessage>();
        for (Opportunity opp : opportunities) {
            Messaging.SingleEmailMessage mail = new Messaging.SingleEmailMessage();
            mail.setTargetObjectId(opp.OwnerId);
            mail.setSaveAsActivity(false);
            mail.setSubject('Renewal due: ' + opp.Name);

            String closeDateText = opp.CloseDate == null ? 'not set' : opp.CloseDate.format();
            mail.setPlainTextBody(
                'Hello ' + opp.Owner.Name + ',\n\n' +
                'The opportunity "' + opp.Name + '" is due for renewal. ' +
                'Its close date is ' + closeDateText + '.\n\n' +
                'Please follow up with the customer.'
            );
            messages.add(mail);
        }

        if (messages.isEmpty()) {
            return 0;
        }

        Integer sentCount = 0;
        try {
            // One call for all messages; allOrNothing=false lets the rest go out if one fails.
            List<Messaging.SendEmailResult> results = Messaging.sendEmail(messages, false);
            for (Integer i = 0; i < results.size(); i++) {
                Messaging.SendEmailResult result = results[i];
                if (result.isSuccess()) {
                    sentCount++;
                } else {
                    for (Messaging.SendEmailError err : result.getErrors()) {
                        System.debug(LoggingLevel.ERROR,
                            'Renewal reminder failed for target ' + err.getTargetObjectId() +
                            ': ' + err.getStatusCode() + ' - ' + err.getMessage());
                    }
                }
            }
        } catch (System.EmailException e) {
            // e.g. email deliverability disabled in the org/sandbox
            System.debug(LoggingLevel.ERROR, 'Renewal reminders could not be sent: ' + e.getMessage());
            return 0;
        }

        return sentCount;
    }
}
