public without sharing class AccountCountrySync {

    // Rows handled inline in the trigger transaction (leaves DML headroom for other automation).
    @TestVisible
    private static final Integer SYNC_PAGE_SIZE = 5000;
    // Rows handled per asynchronous job.
    @TestVisible
    private static final Integer ASYNC_PAGE_SIZE = 9000;

    private static final Id MIN_CONTACT_ID = Id.valueOf('003000000000000AAA');

    public class CountryChange {
        public String oldCountry;
        public String newCountry;
        public CountryChange(String oldCountry, String newCountry) {
            this.oldCountry = oldCountry;
            this.newCountry = newCountry;
        }
    }

    public class PageResult {
        public Boolean hasMore = false;
        public Id lastId;
    }

    public static void handleAfterUpdate(List<Account> newList, Map<Id, Account> oldMap) {
        Map<Id, CountryChange> changes = new Map<Id, CountryChange>();
        for (Account acc : newList) {
            Account oldAcc = oldMap == null ? null : oldMap.get(acc.Id);
            if (oldAcc != null && acc.BillingCountry != oldAcc.BillingCountry) {
                changes.put(acc.Id, new CountryChange(oldAcc.BillingCountry, acc.BillingCountry));
            }
        }
        if (changes.isEmpty()) {
            return;
        }

        PageResult result = processPage(changes, MIN_CONTACT_ID, SYNC_PAGE_SIZE);
        if (result.hasMore) {
            System.enqueueJob(new ContactCountryJob(changes, result.lastId));
        }
    }

    /**
     * Processes one page of candidate contacts (ordered by Id, after the cursor).
     * One SOQL query and at most one DML statement per call.
     */
    public static PageResult processPage(Map<Id, CountryChange> changes, Id cursor, Integer pageSize) {
        PageResult result = new PageResult();

        Set<String> oldCountries = new Set<String>();
        for (CountryChange change : changes.values()) {
            if (String.isNotBlank(change.oldCountry)) {
                oldCountries.add(change.oldCountry);
            }
        }
        Set<Id> accountIds = changes.keySet();

        List<Contact> candidates = [
            SELECT Id, AccountId, MailingCountry
            FROM Contact
            WHERE AccountId IN :accountIds
              AND Id > :cursor
              AND (MailingCountry = null OR MailingCountry IN :oldCountries)
            ORDER BY Id
            LIMIT :pageSize
        ];

        if (candidates.isEmpty()) {
            return result;
        }
        result.lastId = candidates[candidates.size() - 1].Id;
        result.hasMore = candidates.size() == pageSize;

        List<Contact> toUpdate = new List<Contact>();
        for (Contact con : candidates) {
            CountryChange change = changes.get(con.AccountId);
            if (change == null) {
                continue;
            }
            Boolean blankOrOld = String.isBlank(con.MailingCountry)
                || con.MailingCountry == change.oldCountry;
            Boolean alreadyCurrent = (String.isBlank(con.MailingCountry) && String.isBlank(change.newCountry))
                || con.MailingCountry == change.newCountry;
            if (blankOrOld && !alreadyCurrent) {
                toUpdate.add(new Contact(Id = con.Id, MailingCountry = change.newCountry));
            }
        }

        if (!toUpdate.isEmpty()) {
            List<Database.SaveResult> saveResults = Database.update(toUpdate, false);
            for (Integer i = 0; i < saveResults.size(); i++) {
                if (!saveResults[i].isSuccess()) {
                    System.debug(LoggingLevel.ERROR, 'MailingCountry sync failed for Contact '
                        + toUpdate[i].Id + ': ' + saveResults[i].getErrors()[0].getMessage());
                }
            }
        }
        return result;
    }

    /**
     * Continues the sync for accounts with more contacts than fit in one transaction.
     */
    public class ContactCountryJob implements Queueable {
        private Map<Id, CountryChange> changes;
        private Id cursor;

        public ContactCountryJob(Map<Id, CountryChange> changes, Id cursor) {
            this.changes = changes;
            this.cursor = cursor;
        }

        public void execute(QueueableContext ctx) {
            PageResult result = AccountCountrySync.processPage(changes, cursor, ASYNC_PAGE_SIZE);
            if (result.hasMore && !Test.isRunningTest()) {
                System.enqueueJob(new ContactCountryJob(changes, result.lastId));
            }
        }
    }
}
