import { LightningElement, api, wire } from 'lwc';
import { getRecord } from 'lightning/uiRecordApi';

const FIELDS = [
    'Account.Name',
    'Account.Industry',
    'Account.AnnualRevenue',
    'Account.Owner.Name'
];

export default class AccountHeader extends LightningElement {
    // Provided by the record page. Used reactively ($recordId) in the wire,
    // so a new value (e.g. a reused console tab) loads the new record.
    @api recordId;

    record;
    error;

    @wire(getRecord, { recordId: '$recordId', fields: FIELDS })
    wiredRecord({ data, error }) {
        if (data) {
            this.record = data;
            this.error = undefined;
        } else if (error) {
            this.record = undefined;
            this.error = error;
        }
    }

    get isLoading() {
        return !this.record && !this.error;
    }

    get hasData() {
        return !!this.record;
    }

    get hasError() {
        return !!this.error;
    }

    get name() {
        return this.record?.fields?.Name?.value;
    }

    get industry() {
        return this.record?.fields?.Industry?.value;
    }

    get annualRevenue() {
        return this.record?.fields?.AnnualRevenue?.value;
    }

    get ownerName() {
        return this.record?.fields?.Owner?.value?.fields?.Name?.value;
    }

    get errorMessage() {
        const body = this.error?.body;
        if (Array.isArray(body)) {
            return body.map((b) => b.message).join(', ');
        }
        return body?.message ?? this.error?.message;
    }
}
