import { LightningElement, api } from 'lwc';

export default class AccountContactList extends LightningElement {
    // Owned by the parent: never mutated here. A new array from the parent re-renders the list.
    @api contacts;

    get hasContacts() {
        return Array.isArray(this.contacts) && this.contacts.length > 0;
    }

    get countLabel() {
        const count = this.hasContacts ? this.contacts.length : 0;
        return count === 1 ? '1 contact' : `${count} contacts`;
    }

    get sortedContacts() {
        if (!this.hasContacts) {
            return [];
        }
        // Copy first: the public array is read-only and owned by the parent.
        return this.contacts
            .map((c) => ({ Id: c.Id, Name: c.Name, Title: c.Title }))
            .sort((a, b) => (a.Name || '').localeCompare(b.Name || ''));
    }
}
