import { LightningElement } from 'lwc';
import searchContacts from '@salesforce/apex/ContactController.searchContacts';

const DEBOUNCE_DELAY_MS = 300;
const MIN_TERM_LENGTH = 2;

export default class ContactSearch extends LightningElement {
    contacts = [];
    errorMessage;

    _timeoutId;
    _requestId = 0;

    get hasResults() {
        return this.contacts.length > 0;
    }

    handleChange(event) {
        const rawValue =
            event.detail && event.detail.value !== undefined
                ? event.detail.value
                : event.target.value;
        const searchTerm = (rawValue || '').trim();

        // Cancel any pending search
        this.cancelPending();

        if (searchTerm.length < MIN_TERM_LENGTH) {
            // Invalidate any in-flight request so its response is ignored
            this._requestId++;
            this.contacts = [];
            this.errorMessage = undefined;
            return;
        }

        // eslint-disable-next-line @lwc/lwc/no-async-operation
        this._timeoutId = setTimeout(() => {
            this._timeoutId = undefined;
            this.runSearch(searchTerm);
        }, DEBOUNCE_DELAY_MS);
    }

    runSearch(searchTerm) {
        const requestId = ++this._requestId;
        searchContacts({ searchTerm })
            .then((result) => {
                if (requestId !== this._requestId) {
                    return; // stale response
                }
                this.contacts = result || [];
                this.errorMessage = undefined;
            })
            .catch((error) => {
                if (requestId !== this._requestId) {
                    return; // stale response
                }
                this.contacts = [];
                this.errorMessage =
                    (error && error.body && error.body.message) ||
                    (error && error.message) ||
                    'Unknown error';
            });
    }

    cancelPending() {
        if (this._timeoutId !== undefined) {
            clearTimeout(this._timeoutId);
            this._timeoutId = undefined;
        }
    }

    disconnectedCallback() {
        this.cancelPending();
        // Ignore any response still in flight after removal
        this._requestId++;
    }
}
