    handleSubmit() {
        const editors = this.editors;

        // Call validate() on every editor (no short-circuiting) so that
        // all invalid lines display their errors at once.
        const results = editors.map((editor) => editor.validate());
        const allValid = results.every((isValid) => isValid === true);

        if (allValid) {
            this.showError = false;
            this.dispatchEvent(
                new CustomEvent('submit', {
                    detail: { lines: editors.map((editor) => editor.getValue()) }
                })
            );
        } else {
            this.showError = true;
        }
    }
}
