import { LightningElement } from 'lwc';
import getQueueStats from '@salesforce/apex/QueueController.getQueueStats';

const REFRESH_INTERVAL_MS = 60000;

export default class QueueMonitor extends LightningElement {
    stats;
    errorMessage;

    _intervalId;
    _inFlight = false;
    _connected = false;
    _visibilityHandler = () => this.handleVisibilityChange();

    connectedCallback() {
        this._connected = true;
        // Guard against a duplicate listener, so only one is ever registered
        document.removeEventListener('visibilitychange', this._visibilityHandler);
        document.addEventListener('visibilitychange', this._visibilityHandler);
        if (!this.isHidden()) {
            this.startPolling();
        }
    }

    disconnectedCallback() {
        this._connected = false;
        this.stopPolling();
        document.removeEventListener('visibilitychange', this._visibilityHandler);
    }

    isHidden() {
        return document.visibilityState === 'hidden';
    }

    handleVisibilityChange() {
        if (!this._connected) {
            return;
        }
        if (this.isHidden()) {
            this.stopPolling();
        } else {
            this.startPolling();
        }
    }

    startPolling() {
        // Always clear first so there is never more than one loop
        this.stopPolling();
        this.loadStats();
        this._intervalId = setInterval(() => {
            if (this._connected && !this.isHidden()) {
                this.loadStats();
            }
        }, REFRESH_INTERVAL_MS);
    }

    stopPolling() {
        if (this._intervalId !== undefined) {
            clearInterval(this._intervalId);
            this._intervalId = undefined;
        }
    }

    async loadStats() {
        if (this._inFlight || !this._connected || this.isHidden()) {
            return;
        }
        this._inFlight = true;
        try {
            const result = await getQueueStats();
            if (this._connected) {
                this.stats = result;
                this.errorMessage = undefined;
            }
        } catch (error) {
            if (this._connected) {
                this.errorMessage =
                    (error && error.body && error.body.message) ||
                    (error && error.message) ||
                    'Unknown error';
            }
        } finally {
            this._inFlight = false;
        }
    }
}
