import { LightningElement } from 'lwc';
import { ShowToastEvent } from 'lightning/platformShowToastEvent';
import register from '@salesforce/apex/RegistrationController.register';

const PERSONAL_DOMAINS = ['gmail.com', 'yahoo.com', 'hotmail.com', 'outlook.com'];
const WORK_EMAIL_MESSAGE = 'Use your work email address.';

export default class EventRegistrationForm extends LightningElement {
    fullName = '';
    email = '';
    company = '';

    handleChange(event) {
        const field = event.target.dataset.field;
        if (field === 'fullName' || field === 'email' || field === 'company') {
            this[field] = event.detail.value;
        }
    }

    isPersonalEmail(email) {
        const value = (email || '').trim().toLowerCase();
        const at = value.lastIndexOf('@');
        if (at < 0) {
            return false;
        }
        const domain = value.substring(at + 1);
        return PERSONAL_DOMAINS.includes(domain);
    }

    handleRegister() {
        // 1. Work-email check, before reportValidity
        const emailInput = this.template.querySelector('lightning-input[data-field="email"]');
        if (emailInput) {
            emailInput.setCustomValidity(
                this.isPersonalEmail(this.email) ? WORK_EMAIL_MESSAGE : ''
            );
        }

        // 2. Report validity on every input (no short-circuiting)
        const inputs = Array.from(this.template.querySelectorAll('lightning-input'));
        const results = inputs.map((input) => input.reportValidity());
        const allValid = results.every((valid) => valid === true);

        // 3. Stop if any invalid
        if (!allValid) {
            return;
        }

        register({
            fullName: this.fullName,
            email: this.email,
            company: this.company
        })
            .then(() => {
                this.dispatchEvent(
                    new ShowToastEvent({
                        title: 'Registered',
                        message: 'You have been registered for the event.',
                        variant: 'success'
                    })
                );
            })
            .catch((error) => {
                this.dispatchEvent(
                    new ShowToastEvent({
                        title: 'Registration failed',
                        message: error && error.body ? error.body.message : undefined,
                        variant: 'error'
                    })
                );
            });
    }
}
