import { LightningElement, api } from 'lwc';

const HANDLED_KEYS = ['ArrowDown', 'ArrowUp', 'Home', 'End', 'Enter', ' '];

export default class StatusListbox extends LightningElement {
    @api label;

    _options = [];
    _value;
    _activeValue;

    @api
    get options() {
        return this._options;
    }
    set options(val) {
        this._options = Array.isArray(val) ? val : [];
    }

    @api
    get value() {
        return this._value;
    }
    set value(val) {
        this._value = val;
        // The active option follows the selection whenever the parent changes it.
        this._activeValue = val;
    }

    // ---------- derived state ----------

    isSelectedValue(optionValue) {
        return (
            this._value !== undefined &&
            this._value !== null &&
            this._value === optionValue
        );
    }

    get activeIndex() {
        const opts = this._options;
        if (!opts.length) {
            return -1;
        }
        if (this._activeValue !== undefined && this._activeValue !== null) {
            const idx = opts.findIndex((o) => o.value === this._activeValue);
            if (idx >= 0) {
                return idx;
            }
        }
        const selectedIdx = opts.findIndex((o) => this.isSelectedValue(o.value));
        return selectedIdx >= 0 ? selectedIdx : 0;
    }

    get activeDescendantId() {
        const idx = this.activeIndex;
        return idx >= 0 ? this.optionId(idx) : undefined;
    }

    optionId(index) {
        return `option-${index}`;
    }

    get items() {
        return this._options.map((opt, index) => ({
            key: this.optionId(index),
            id: this.optionId(index),
            index,
            value: opt.value,
            label: opt.label,
            selected: this.isSelectedValue(opt.value) ? 'true' : 'false'
        }));
    }

    // ---------- behaviour ----------

    setActiveIndex(index) {
        const opt = this._options[index];
        if (opt) {
            this._activeValue = opt.value;
        }
    }

    selectIndex(index) {
        const opt = this._options[index];
        if (!opt) {
            return;
        }
        this._activeValue = opt.value;
        if (this.isSelectedValue(opt.value)) {
            return;
        }
        this._value = opt.value;
        this.dispatchEvent(
            new CustomEvent('change', { detail: { value: opt.value } })
        );
    }

    handleKeydown(event) {
        const key = event.key;
        if (!HANDLED_KEYS.includes(key)) {
            return;
        }
        event.preventDefault();

        const count = this._options.length;
        if (!count) {
            return;
        }
        const current = this.activeIndex;

        switch (key) {
            case 'ArrowDown':
                this.setActiveIndex(Math.min(current + 1, count - 1));
                break;
            case 'ArrowUp':
                this.setActiveIndex(Math.max(current - 1, 0));
                break;
            case 'Home':
                this.setActiveIndex(0);
                break;
            case 'End':
                this.setActiveIndex(count - 1);
                break;
            case 'Enter':
            case ' ':
                this.selectIndex(current);
                break;
            default:
                break;
        }
    }

    handleClick(event) {
        const index = Number(event.currentTarget.dataset.index);
        if (!Number.isNaN(index)) {
            this.selectIndex(index);
        }
    }
}
