    get tasks() {
        return this._tasks;
    }
    set tasks(value) {
        this._tasks = value;
        this.items = Array.isArray(value)
            ? value.map((task) => ({ ...task }))
            : [];
    }

    get displayHeading() {
        return this._heading ? String(this._heading).toUpperCase() : '';
    }

    get remaining() {
        return this.items.filter((task) => !task.done).length;
    }

    generateId() {
        const existing = new Set(this.items.map((task) => String(task.id)));
        let id = `new-${this.nextId++}`;
        while (existing.has(id)) {
            id = `new-${this.nextId++}`;
        }
        return id;
    }

    handleLabelChange(event) {
        this.newLabel = event.detail.value;
    }

    handleAdd() {
        const label = (this.newLabel || '').trim();
        if (!label) {
            return;
        }
        const newTask = { id: this.generateId(), label, done: false };
        this.items = [...this.items, newTask];
        this.newLabel = '';
        this.dispatchEvent(new CustomEvent('taskadded', { detail: { label } }));
    }

    handleToggle(event) {
        const id = String(event.currentTarget.dataset.id);
        this.items = this.items.map((task) =>
            String(task.id) === id ? { ...task, done: !task.done } : task
        );
    }
}
