public with sharing class EmployerService {

    /**
     * Makes the given organization the Current, primary affiliation of each contact.
     *
     * The affiliation is created (or an existing one for the same contact and organization is
     * reactivated) with npe5__Primary__c = true. NPSP's affiliation trigger handler then sets
     * Contact.npsp__Primary_Affiliation__c and turns the previous primary affiliation into a
     * Former, non-primary one with an end date of today. Contact.AccountId (the household) is never
     * touched.
     *
     * Cost: 1 SOQL query, at most 2 DML statements (1 insert, 1 update).
     */
    public static void setCurrentEmployers(Map<Id, Id> employerByContactId) {
        if (employerByContactId == null || employerByContactId.isEmpty()) {
            return;
        }

        // Keep only usable pairs
        Map<Id, Id> wanted = new Map<Id, Id>();
        Set<Id> orgIds = new Set<Id>();
        for (Id contactId : employerByContactId.keySet()) {
            Id orgId = employerByContactId.get(contactId);
            if (contactId != null && orgId != null) {
                wanted.put(contactId, orgId);
                orgIds.add(orgId);
            }
        }
        if (wanted.isEmpty()) {
            return;
        }

        // One query for all existing affiliations between these contacts and these organizations.
        // The cross product (contact x org) is filtered to the exact pairs below.
        Map<String, List<npe5__Affiliation__c>> existingByPair = new Map<String, List<npe5__Affiliation__c>>();
        for (npe5__Affiliation__c a : [
            SELECT Id, npe5__Contact__c, npe5__Organization__c, npe5__Status__c,
                   npe5__Primary__c, npe5__StartDate__c, npe5__EndDate__c
            FROM npe5__Affiliation__c
            WHERE npe5__Contact__c IN :wanted.keySet()
            AND npe5__Organization__c IN :orgIds
            WITH USER_MODE
            ORDER BY CreatedDate DESC
        ]) {
            if (wanted.get(a.npe5__Contact__c) != a.npe5__Organization__c) {
                continue;
            }
            String key = pairKey(a.npe5__Contact__c, a.npe5__Organization__c);
            if (!existingByPair.containsKey(key)) {
                existingByPair.put(key, new List<npe5__Affiliation__c>());
            }
            existingByPair.get(key).add(a);
        }

        List<npe5__Affiliation__c> toInsert = new List<npe5__Affiliation__c>();
        List<npe5__Affiliation__c> toUpdate = new List<npe5__Affiliation__c>();
        Date today = Date.today();

        for (Id contactId : wanted.keySet()) {
            Id orgId = wanted.get(contactId);
            List<npe5__Affiliation__c> existing = existingByPair.get(pairKey(contactId, orgId));

            if (existing == null || existing.isEmpty()) {
                toInsert.add(new npe5__Affiliation__c(
                    npe5__Contact__c = contactId,
                    npe5__Organization__c = orgId,
                    npe5__Status__c = 'Current',
                    npe5__Primary__c = true,
                    npe5__StartDate__c = today
                ));
                continue;
            }

            // Already the Current primary affiliation: nothing to do
            Boolean alreadyPrimary = false;
            npe5__Affiliation__c candidate = null;
            for (npe5__Affiliation__c a : existing) {
                if (a.npe5__Primary__c && a.npe5__Status__c == 'Current') {
                    alreadyPrimary = true;
                    break;
                }
                // Prefer a Current one, otherwise the most recently created (list is newest first)
                if (candidate == null
                    || (candidate.npe5__Status__c != 'Current' && a.npe5__Status__c == 'Current')) {
                    candidate = a;
                }
            }
            if (alreadyPrimary) {
                continue;
            }

            // Reuse the existing affiliation instead of creating a duplicate
            npe5__Affiliation__c upd = new npe5__Affiliation__c(
                Id = candidate.Id,
                npe5__Status__c = 'Current',
                npe5__Primary__c = true,
                npe5__EndDate__c = null
            );
            if (candidate.npe5__StartDate__c == null) {
                upd.npe5__StartDate__c = today;
            }
            toUpdate.add(upd);
        }

        if (!toInsert.isEmpty()) {
            insert as user toInsert;
        }
        if (!toUpdate.isEmpty()) {
            update as user toUpdate;
        }
    }

    private static String pairKey(Id contactId, Id orgId) {
        return String.valueOf(contactId) + '|' + String.valueOf(orgId);
    }
}
