public with sharing class RecurringGiftService {

    public class RecurringGiftException extends Exception {}

    public class GiftRequest {
        public Id contactId;
        public Decimal amount;
        public Integer dayOfMonth;    // 1-31
        public Date startDate;
        public Integer installments;  // null or 0 = no end date
        public String paymentMethod;  // 'Credit Card', 'ACH' or 'Check'
    }

    private static final String LAST_DAY_OF_MONTH = 'Last_Day';

    public static List<Id> createMonthlyGifts(List<GiftRequest> requests) {
        List<Id> result = new List<Id>();
        if (requests == null || requests.isEmpty()) {
            return result;
        }

        // 1. Validate everything before any query or DML
        Set<Id> contactIds = new Set<Id>();
        for (Integer i = 0; i < requests.size(); i++) {
            GiftRequest req = requests[i];
            if (req == null) {
                throw new RecurringGiftException('Request at index ' + i + ' is null.');
            }
            if (req.contactId == null) {
                throw new RecurringGiftException('Request at index ' + i + ' has no contact.');
            }
            if (req.amount == null || req.amount <= 0) {
                throw new RecurringGiftException('Request at index ' + i + ' must have an amount greater than zero.');
            }
            if (req.dayOfMonth == null || req.dayOfMonth < 1 || req.dayOfMonth > 31) {
                throw new RecurringGiftException('Request at index ' + i + ' must have a day of month between 1 and 31.');
            }
            if (req.startDate == null) {
                throw new RecurringGiftException('Request at index ' + i + ' has no start date.');
            }
            if (req.installments != null && req.installments < 0) {
                throw new RecurringGiftException('Request at index ' + i + ' has a negative number of installments.');
            }
            contactIds.add(req.contactId);
        }

        // 2. Single query: confirm contacts exist (and are visible) and get names for naming
        Map<Id, Contact> contacts = new Map<Id, Contact>(
            [SELECT Id, FirstName, LastName FROM Contact WHERE Id IN :contactIds WITH USER_MODE]
        );
        for (Integer i = 0; i < requests.size(); i++) {
            if (!contacts.containsKey(requests[i].contactId)) {
                throw new RecurringGiftException('Request at index ' + i + ' references a contact that was not found.');
            }
        }

        // 3. Build the Enhanced Recurring Donations (no Opportunities: NPSP creates the installments)
        List<npe03__Recurring_Donation__c> donations = new List<npe03__Recurring_Donation__c>();
        for (GiftRequest req : requests) {
            Contact c = contacts.get(req.contactId);
            String donorName = String.isBlank(c.FirstName) ? c.LastName : c.FirstName + ' ' + c.LastName;

            npe03__Recurring_Donation__c rd = new npe03__Recurring_Donation__c(
                Name = (donorName + ' Monthly Recurring Gift').left(80),
                npe03__Contact__c = req.contactId,
                npe03__Amount__c = req.amount,
                npe03__Installment_Period__c = 'Monthly',
                npsp__InstallmentFrequency__c = 1,
                npsp__StartDate__c = req.startDate,
                npe03__Date_Established__c = Date.today(),
                npsp__Status__c = 'Active',
                npsp__PaymentMethod__c = req.paymentMethod
            );

            // 31 means "last day of the month" -> ERD's own Last_Day option
            rd.npsp__Day_of_Month__c = (req.dayOfMonth == 31)
                ? LAST_DAY_OF_MONTH
                : String.valueOf(req.dayOfMonth);

            if (req.installments == null || req.installments == 0) {
                rd.npsp__RecurringType__c = 'Open';
            } else {
                rd.npsp__RecurringType__c = 'Fixed';
                rd.npe03__Installments__c = req.installments;
            }

            donations.add(rd);
        }

        // 4. Single DML (all-or-none)
        Database.insert(donations, AccessLevel.USER_MODE);

        for (npe03__Recurring_Donation__c rd : donations) {
            result.add(rd.Id);
        }
        return result;
    }
}
