public with sharing class GauAllocationService {

    public class AllocationException extends Exception {}

    public static List<npsp__Allocation__c> allocateByPercent(Id opportunityId, Map<Id, Decimal> percentByGauId) {

        // ---------- Validation (no data is changed until all checks pass) ----------
        if (opportunityId == null) {
            throw new AllocationException('An opportunity Id is required.');
        }
        if (percentByGauId == null || percentByGauId.isEmpty()) {
            throw new AllocationException('At least one GAU percentage is required.');
        }

        Decimal total = 0;
        for (Id gauId : percentByGauId.keySet()) {
            if (gauId == null) {
                throw new AllocationException('A GAU Id in the map is null.');
            }
            Decimal pct = percentByGauId.get(gauId);
            if (pct == null || pct <= 0) {
                throw new AllocationException('Percentage for GAU ' + gauId + ' must be greater than 0.');
            }
            total += pct;
        }
        if (total > 100) {
            throw new AllocationException('Percentages add up to ' + total + '%, which is more than 100%.');
        }

        List<Opportunity> opps = [
            SELECT Id FROM Opportunity WHERE Id = :opportunityId WITH USER_MODE LIMIT 1
        ];
        if (opps.isEmpty()) {
            throw new AllocationException('Opportunity ' + opportunityId + ' was not found.');
        }

        Map<Id, npsp__General_Accounting_Unit__c> gaus = new Map<Id, npsp__General_Accounting_Unit__c>([
            SELECT Id, Name, npsp__Active__c
            FROM npsp__General_Accounting_Unit__c
            WHERE Id IN :percentByGauId.keySet()
            WITH USER_MODE
        ]);
        for (Id gauId : percentByGauId.keySet()) {
            npsp__General_Accounting_Unit__c gau = gaus.get(gauId);
            if (gau == null) {
                throw new AllocationException('GAU ' + gauId + ' was not found.');
            }
            if (gau.npsp__Active__c != true) {
                throw new AllocationException('GAU "' + gau.Name + '" is inactive.');
            }
        }

        // ---------- Build new allocations ----------
        // Only npsp__Percent__c is set; npsp__Amount__c is left blank so NPSP derives it
        // from the opportunity amount and recalculates it whenever that amount changes.
        List<npsp__Allocation__c> toInsert = new List<npsp__Allocation__c>();
        for (Id gauId : percentByGauId.keySet()) {
            toInsert.add(new npsp__Allocation__c(
                npsp__Opportunity__c = opportunityId,
                npsp__General_Accounting_Unit__c = gauId,
                npsp__Percent__c = percentByGauId.get(gauId)
            ));
        }

        // ---------- Replace existing allocations ----------
        Savepoint sp = Database.setSavepoint();
        try {
            List<npsp__Allocation__c> existing = [
                SELECT Id
                FROM npsp__Allocation__c
                WHERE npsp__Opportunity__c = :opportunityId
                   OR npsp__Payment__r.npsp__Opportunity__c = :opportunityId
                WITH USER_MODE
            ];
            if (!existing.isEmpty()) {
                Database.delete(existing, true, AccessLevel.USER_MODE);
            }

            Database.insert(toInsert, true, AccessLevel.USER_MODE);
        } catch (Exception e) {
            Database.rollback(sp);
            throw e;
        }

        // Re-query so calculated amounts are included in the returned records
        Set<Id> insertedIds = new Map<Id, npsp__Allocation__c>(toInsert).keySet();
        return [
            SELECT Id, npsp__Opportunity__c, npsp__General_Accounting_Unit__c,
                   npsp__Amount__c, npsp__Percent__c
            FROM npsp__Allocation__c
            WHERE Id IN :insertedIds
            WITH USER_MODE
        ];
    }
}
