public with sharing class HouseholdService {

    private static final String HH_RT_DEVELOPER_NAME = 'HH_Account';

    public static Id createHousehold(List<Contact> members) {
        if (members == null || members.isEmpty()) {
            throw new IllegalArgumentException('members must contain at least one Contact.');
        }
        for (Contact c : members) {
            if (c == null) {
                throw new IllegalArgumentException('members must not contain null entries.');
            }
        }

        Savepoint sp = Database.setSavepoint();
        try {
            // Insert only the first contact. In the Household Account model NPSP creates
            // exactly one Household Account (named by NPSP, with the Household record type)
            // for a contact that has no AccountId. Inserting all contacts at once would make
            // NPSP create one household per contact.
            Contact primary = members[0];
            insert primary;

            // NPSP assigns the AccountId in a separate DML in its trigger, so re-query.
            Contact inserted = [
                SELECT Id, AccountId
                FROM Contact
                WHERE Id = :primary.Id
            ];
            Id accountId = inserted.AccountId;
            if (accountId == null) {
                throw new HouseholdServiceException(
                    'NPSP did not create a household account for the primary contact.');
            }

            // Remaining members join the same household.
            List<Contact> others = new List<Contact>();
            for (Integer i = 1; i < members.size(); i++) {
                members[i].AccountId = accountId;
                others.add(members[i]);
            }
            if (!others.isEmpty()) {
                insert others;
            }

            // Make sure the account is a real Household Account and the primary contact is set.
            Account acct = [
                SELECT Id, RecordType.DeveloperName, npe01__One2OneContact__c
                FROM Account
                WHERE Id = :accountId
            ];
            Boolean changed = false;

            if (acct.RecordType == null || acct.RecordType.DeveloperName != HH_RT_DEVELOPER_NAME_SAFE()) {
                Schema.RecordTypeInfo rti = Schema.SObjectType.Account
                    .getRecordTypeInfosByDeveloperName().get(HH_RT_DEVELOPER_NAME);
                if (rti == null) {
                    throw new HouseholdServiceException(
                        'Account record type ' + HH_RT_DEVELOPER_NAME + ' was not found.');
                }
                acct.RecordTypeId = rti.getRecordTypeId();
                changed = true;
            }
            if (acct.npe01__One2OneContact__c != primary.Id) {
                acct.npe01__One2OneContact__c = primary.Id;
                changed = true;
            }
            if (changed) {
                update acct;
            }

            return accountId;
        } catch (Exception e) {
            Database.rollback(sp);
            throw e;
        }
    }

    private static String HH_RT_DEVELOPER_NAME_SAFE() {
        return HH_RT_DEVELOPER_NAME;
    }

    public class HouseholdServiceException extends Exception {}
}
