public with sharing class SoftCreditService {

    public class SoftCreditException extends Exception {}

    public class SoftCreditRequest {
        public Id opportunityId;
        public Id contactId;
        public Decimal amount;
        public String role;
    }

    private static String keyOf(Id opportunityId, Id contactId) {
        return String.valueOf(opportunityId) + '|' + String.valueOf(contactId);
    }

    private static Boolean sameId(String textId, Id realId) {
        return String.isNotBlank(textId)
            && realId != null
            && textId.length() >= 15
            && textId.left(15) == String.valueOf(realId).left(15);
    }

    public static void addPartialSoftCredits(List<SoftCreditRequest> requests) {
        if (requests == null || requests.isEmpty()) {
            return;
        }

        // ---------- Collect ids ----------
        Set<Id> oppIds = new Set<Id>();
        Set<Id> contactIds = new Set<Id>();
        for (SoftCreditRequest req : requests) {
            if (req == null || req.opportunityId == null || req.contactId == null) {
                throw new SoftCreditException(
                    'Each request needs an opportunityId and a contactId.');
            }
            oppIds.add(req.opportunityId);
            contactIds.add(req.contactId);
        }

        // ---------- Query 1: opportunities ----------
        Map<Id, Opportunity> opps = new Map<Id, Opportunity>([
            SELECT Id, Amount, npsp__Primary_Contact__c
            FROM Opportunity
            WHERE Id IN :oppIds
            WITH USER_MODE
        ]);

        // ---------- Validate everything before any DML ----------
        for (SoftCreditRequest req : requests) {
            Opportunity opp = opps.get(req.opportunityId);
            if (opp == null) {
                throw new SoftCreditException(
                    'Opportunity not found or not accessible: ' + req.opportunityId);
            }
            if (opp.npsp__Primary_Contact__c != null
                && opp.npsp__Primary_Contact__c == req.contactId) {
                throw new SoftCreditException(
                    'Contact ' + req.contactId + ' is the primary contact of opportunity '
                    + req.opportunityId + ' and cannot receive a partial soft credit.');
            }
            if (req.amount == null || req.amount <= 0) {
                throw new SoftCreditException(
                    'Amount must be a positive number for opportunity '
                    + req.opportunityId + ' and contact ' + req.contactId + '.');
            }
            if (opp.Amount == null || req.amount > opp.Amount) {
                throw new SoftCreditException(
                    'Amount cannot exceed the opportunity amount for opportunity '
                    + req.opportunityId + '.');
            }
        }

        // ---------- Query 2: existing contact roles ----------
        Map<String, List<OpportunityContactRole>> rolesByKey =
            new Map<String, List<OpportunityContactRole>>();
        for (OpportunityContactRole ocr : [
            SELECT Id, OpportunityId, ContactId, Role
            FROM OpportunityContactRole
            WHERE OpportunityId IN :oppIds AND ContactId IN :contactIds
            WITH USER_MODE
            ORDER BY CreatedDate, Id
        ]) {
            String k = keyOf(ocr.OpportunityId, ocr.ContactId);
            if (!rolesByKey.containsKey(k)) {
                rolesByKey.put(k, new List<OpportunityContactRole>());
            }
            rolesByKey.get(k).add(ocr);
        }

        // ---------- Query 3: existing partial soft credits ----------
        Map<String, List<npsp__Partial_Soft_Credit__c>> pscByKey =
            new Map<String, List<npsp__Partial_Soft_Credit__c>>();
        for (npsp__Partial_Soft_Credit__c psc : [
            SELECT Id, npsp__Opportunity__c, npsp__Contact__c, npsp__Amount__c,
                   npsp__Role_Name__c, npsp__Contact_Role_ID__c
            FROM npsp__Partial_Soft_Credit__c
            WHERE npsp__Opportunity__c IN :oppIds AND npsp__Contact__c IN :contactIds
            WITH USER_MODE
            ORDER BY CreatedDate, Id
        ]) {
            String k = keyOf(psc.npsp__Opportunity__c, psc.npsp__Contact__c);
            if (!pscByKey.containsKey(k)) {
                pscByKey.put(k, new List<npsp__Partial_Soft_Credit__c>());
            }
            pscByKey.get(k).add(psc);
        }

        // ---------- Decide which contact role each request uses ----------
        List<OpportunityContactRole> targetRoles = new List<OpportunityContactRole>();
        List<OpportunityContactRole> rolesToUpsert = new List<OpportunityContactRole>();
        List<OpportunityContactRole> rolesToDelete = new List<OpportunityContactRole>();
        List<npsp__Partial_Soft_Credit__c> pscsToDelete = new List<npsp__Partial_Soft_Credit__c>();

        for (SoftCreditRequest req : requests) {
            String k = keyOf(req.opportunityId, req.contactId);
            List<OpportunityContactRole> existingRoles = rolesByKey.get(k);
            List<npsp__Partial_Soft_Credit__c> existingPscs = pscByKey.get(k);

            OpportunityContactRole keep;
            if (existingRoles != null && !existingRoles.isEmpty()) {
                // 1) prefer the role the existing soft credit already points at
                if (existingPscs != null) {
                    for (npsp__Partial_Soft_Credit__c psc : existingPscs) {
                        for (OpportunityContactRole ocr : existingRoles) {
                            if (sameId(psc.npsp__Contact_Role_ID__c, ocr.Id)) {
                                keep = ocr;
                                break;
                            }
                        }
                        if (keep != null) {
                            break;
                        }
                    }
                }
                // 2) then one that already has the right role
                if (keep == null) {
                    for (OpportunityContactRole ocr : existingRoles) {
                        if (ocr.Role == req.role) {
                            keep = ocr;
                            break;
                        }
                    }
                }
                // 3) otherwise the oldest one
                if (keep == null) {
                    keep = existingRoles[0];
                }
                for (OpportunityContactRole ocr : existingRoles) {
                    if (ocr.Id != keep.Id) {
                        rolesToDelete.add(ocr);
                    }
                }
                if (keep.Role != req.role) {
                    keep.Role = req.role;
                    rolesToUpsert.add(keep);
                }
            } else {
                keep = new OpportunityContactRole(
                    OpportunityId = req.opportunityId,
                    ContactId = req.contactId,
                    Role = req.role
                );
                rolesToUpsert.add(keep);
            }
            targetRoles.add(keep);

            if (existingPscs != null && existingPscs.size() > 1) {
                for (Integer i = 1; i < existingPscs.size(); i++) {
                    pscsToDelete.add(existingPscs[i]);
                }
            }
        }

        // ---------- DML 1: insert/update contact roles ----------
        if (!rolesToUpsert.isEmpty()) {
            upsert as user rolesToUpsert;
        }

        // ---------- Build partial soft credits ----------
        List<npsp__Partial_Soft_Credit__c> pscsToUpsert = new List<npsp__Partial_Soft_Credit__c>();
        for (Integer i = 0; i < requests.size(); i++) {
            SoftCreditRequest req = requests[i];
            OpportunityContactRole ocr = targetRoles[i];
            List<npsp__Partial_Soft_Credit__c> existingPscs =
                pscByKey.get(keyOf(req.opportunityId, req.contactId));

            npsp__Partial_Soft_Credit__c psc;
            if (existingPscs != null && !existingPscs.isEmpty()) {
                psc = existingPscs[0];
            } else {
                psc = new npsp__Partial_Soft_Credit__c(
                    npsp__Opportunity__c = req.opportunityId,
                    npsp__Contact__c = req.contactId
                );
            }
            psc.npsp__Amount__c = req.amount;
            psc.npsp__Role_Name__c = req.role;
            psc.npsp__Contact_Role_ID__c = String.valueOf(ocr.Id);
            pscsToUpsert.add(psc);
        }

        // ---------- DML 2: insert/update partial soft credits ----------
        if (!pscsToUpsert.isEmpty()) {
            upsert as user pscsToUpsert;
        }

        // ---------- DML 3: remove duplicate partial soft credits ----------
        if (!pscsToDelete.isEmpty()) {
            delete as user pscsToDelete;
        }

        // ---------- DML 4: remove duplicate contact roles ----------
        if (!rolesToDelete.isEmpty()) {
            delete as user rolesToDelete;
        }
    }
}
