public with sharing class PaymentPlanService {

    public class PaymentPlanException extends Exception {}

    public static List<npe01__OppPayment__c> scheduleInstallments(
        Id opportunityId,
        Integer numberOfPayments,
        Date firstPaymentDate
    ) {
        // ---- Input validation (nothing has been changed yet) ----
        if (opportunityId == null) {
            throw new PaymentPlanException('An opportunity is required.');
        }
        if (numberOfPayments == null || numberOfPayments < 1) {
            throw new PaymentPlanException('The number of payments must be at least 1.');
        }
        if (firstPaymentDate == null) {
            throw new PaymentPlanException('The first payment date is required.');
        }

        // Lock the opportunity so concurrent plan changes are serialized
        List<Opportunity> opps = [
            SELECT Id, Amount, IsClosed
            FROM Opportunity
            WHERE Id = :opportunityId
            LIMIT 1
            FOR UPDATE
        ];
        if (opps.isEmpty()) {
            throw new PaymentPlanException('Opportunity not found or not accessible.');
        }
        Opportunity opp = opps[0];
        if (opp.IsClosed) {
            throw new PaymentPlanException('Payments cannot be scheduled for a closed opportunity.');
        }

        List<npe01__OppPayment__c> existing = [
            SELECT Id, npe01__Payment_Amount__c, npe01__Paid__c, npe01__Written_Off__c
            FROM npe01__OppPayment__c
            WHERE npe01__Opportunity__c = :opportunityId
            WITH USER_MODE
            FOR UPDATE
        ];

        Decimal historyTotal = 0;
        List<npe01__OppPayment__c> toDelete = new List<npe01__OppPayment__c>();
        for (npe01__OppPayment__c p : existing) {
            if (p.npe01__Paid__c == true || p.npe01__Written_Off__c == true) {
                historyTotal += (p.npe01__Payment_Amount__c == null ? 0 : p.npe01__Payment_Amount__c);
            } else {
                toDelete.add(p);
            }
        }

        Decimal oppAmount = opp.Amount == null ? 0 : opp.Amount;
        Decimal outstanding = oppAmount - historyTotal;
        if (outstanding <= 0) {
            throw new PaymentPlanException('There is no outstanding amount to schedule.');
        }

        // ---- Build the new payments ----
        Decimal baseAmount = outstanding.divide(numberOfPayments, 2, RoundingMode.DOWN);
        Decimal lastAmount = outstanding - (baseAmount * (numberOfPayments - 1));

        List<npe01__OppPayment__c> newPayments = new List<npe01__OppPayment__c>();
        for (Integer i = 0; i < numberOfPayments; i++) {
            newPayments.add(new npe01__OppPayment__c(
                npe01__Opportunity__c = opportunityId,
                npe01__Payment_Amount__c = (i == numberOfPayments - 1) ? lastAmount : baseAmount,
                npe01__Scheduled_Date__c = firstPaymentDate.addMonths(i),
                npe01__Paid__c = false,
                npe01__Written_Off__c = false
            ));
        }

        // ---- DML, all or nothing ----
        Savepoint sp = Database.setSavepoint();
        try {
            if (!toDelete.isEmpty()) {
                delete as user toDelete;
            }
            insert as user newPayments;
        } catch (Exception e) {
            Database.rollback(sp);
            throw e;
        }

        return newPayments;
    }
}
