public with sharing class GiftService {

    private static final String ROLE_DONOR = 'Donor';
    private static final String ROLE_HOUSEHOLD_MEMBER = 'Household Member';
    private static final String STAGE_CLOSED_WON = 'Closed Won';

    public static Id recordGift(Id contactId, Decimal amount, Date giftDate) {
        if (contactId == null) {
            throw new IllegalArgumentException('A contact is required.');
        }
        if (amount == null || amount <= 0) {
            throw new IllegalArgumentException('Amount must be greater than zero.');
        }
        if (giftDate == null) {
            throw new IllegalArgumentException('Gift date is required.');
        }

        List<Contact> contacts = [
            SELECT Id, FirstName, LastName, AccountId
            FROM Contact
            WHERE Id = :contactId
            LIMIT 1
        ];
        if (contacts.isEmpty()) {
            throw new IllegalArgumentException('Contact not found: ' + contactId);
        }
        Contact donor = contacts[0];

        // Household members (including the donor)
        Set<Id> householdContactIds = new Set<Id>{ donor.Id };
        if (donor.AccountId != null) {
            for (Contact c : [
                SELECT Id FROM Contact WHERE AccountId = :donor.AccountId
            ]) {
                householdContactIds.add(c.Id);
            }
        }

        String dateText = DateTime.newInstance(giftDate, Time.newInstance(0, 0, 0, 0))
            .format('yyyy-MM-dd');
        List<String> nameParts = new List<String>();
        if (String.isNotBlank(donor.FirstName)) {
            nameParts.add(donor.FirstName.trim());
        }
        if (String.isNotBlank(donor.LastName)) {
            nameParts.add(donor.LastName.trim());
        }
        nameParts.add('Donation');
        nameParts.add(dateText);
        String oppName = String.join(nameParts, ' ');
        if (oppName.length() > 120) {
            oppName = oppName.substring(0, 120);
        }

        Opportunity opp = new Opportunity(
            Name = oppName,
            AccountId = donor.AccountId,
            npsp__Primary_Contact__c = donor.Id,
            StageName = STAGE_CLOSED_WON,
            CloseDate = giftDate,
            Amount = amount
        );
        insert as user opp;

        // NPSP automation may already have created roles and/or a payment: reconcile, don't blindly add.
        reconcileContactRoles(opp.Id, donor.Id, householdContactIds);
        reconcilePayment(opp.Id, amount, giftDate);

        return opp.Id;
    }

    private static void reconcileContactRoles(Id oppId, Id donorId, Set<Id> householdContactIds) {
        Map<Id, List<OpportunityContactRole>> existingByContact = new Map<Id, List<OpportunityContactRole>>();
        for (OpportunityContactRole ocr : [
            SELECT Id, ContactId, Role, IsPrimary
            FROM OpportunityContactRole
            WHERE OpportunityId = :oppId
            ORDER BY CreatedDate, Id
        ]) {
            if (!existingByContact.containsKey(ocr.ContactId)) {
                existingByContact.put(ocr.ContactId, new List<OpportunityContactRole>());
            }
            existingByContact.get(ocr.ContactId).add(ocr);
        }

        List<OpportunityContactRole> toInsert = new List<OpportunityContactRole>();
        List<OpportunityContactRole> toUpdate = new List<OpportunityContactRole>();
        List<OpportunityContactRole> toDelete = new List<OpportunityContactRole>();

        for (Id cId : householdContactIds) {
            Boolean isDonor = (cId == donorId);
            String desiredRole = isDonor ? ROLE_DONOR : ROLE_HOUSEHOLD_MEMBER;
            List<OpportunityContactRole> existing = existingByContact.get(cId);

            if (existing == null || existing.isEmpty()) {
                toInsert.add(new OpportunityContactRole(
                    OpportunityId = oppId,
                    ContactId = cId,
                    Role = desiredRole,
                    IsPrimary = isDonor
                ));
                continue;
            }

            // Keep one role (prefer one that already has the desired role), delete the rest
            Integer keepIdx = 0;
            for (Integer i = 0; i < existing.size(); i++) {
                if (existing[i].Role == desiredRole) {
                    keepIdx = i;
                    break;
                }
            }
            for (Integer i = 0; i < existing.size(); i++) {
                OpportunityContactRole ocr = existing[i];
                if (i != keepIdx) {
                    toDelete.add(ocr);
                    continue;
                }
                Boolean changed = false;
                if (ocr.Role != desiredRole) {
                    ocr.Role = desiredRole;
                    changed = true;
                }
                if (isDonor && !ocr.IsPrimary) {
                    ocr.IsPrimary = true;
                    changed = true;
                } else if (!isDonor && ocr.IsPrimary) {
                    ocr.IsPrimary = false;
                    changed = true;
                }
                if (changed) {
                    toUpdate.add(ocr);
                }
            }
        }

        if (!toDelete.isEmpty()) {
            delete as user toDelete;
        }
        if (!toUpdate.isEmpty()) {
            update as user toUpdate;
        }
        if (!toInsert.isEmpty()) {
            insert as user toInsert;
        }
    }

    private static void reconcilePayment(Id oppId, Decimal amount, Date giftDate) {
        List<npe01__OppPayment__c> payments = [
            SELECT Id, npe01__Payment_Amount__c, npe01__Payment_Date__c,
                   npe01__Scheduled_Date__c, npe01__Paid__c
            FROM npe01__OppPayment__c
            WHERE npe01__Opportunity__c = :oppId
            ORDER BY CreatedDate, Id
        ];

        if (payments.isEmpty()) {
            insert as user new npe01__OppPayment__c(
                npe01__Opportunity__c = oppId,
                npe01__Payment_Amount__c = amount,
                npe01__Payment_Date__c = giftDate,
                npe01__Scheduled_Date__c = giftDate,
                npe01__Paid__c = true
            );
            return;
        }

        // Prefer keeping a payment that is already correct
        Integer keepIdx = 0;
        for (Integer i = 0; i < payments.size(); i++) {
            npe01__OppPayment__c p = payments[i];
            if (p.npe01__Paid__c == true
                && p.npe01__Payment_Amount__c == amount
                && p.npe01__Payment_Date__c == giftDate) {
                keepIdx = i;
                break;
            }
        }

        List<npe01__OppPayment__c> toDelete = new List<npe01__OppPayment__c>();
        for (Integer i = 0; i < payments.size(); i++) {
            if (i != keepIdx) {
                toDelete.add(payments[i]);
            }
        }
        if (!toDelete.isEmpty()) {
            delete as user toDelete;
        }

        npe01__OppPayment__c keep = payments[keepIdx];
        if (keep.npe01__Paid__c != true
            || keep.npe01__Payment_Amount__c != amount
            || keep.npe01__Payment_Date__c != giftDate
            || keep.npe01__Scheduled_Date__c != giftDate) {
            keep.npe01__Payment_Amount__c = amount;
            keep.npe01__Payment_Date__c = giftDate;
            keep.npe01__Scheduled_Date__c = giftDate;
            keep.npe01__Paid__c = true;
            update as user keep;
        }
    }
}
