public with sharing class FamilyService {

    private static final String PARENT_TYPE = 'Parent';
    private static final String CURRENT_STATUS = 'Current';

    /**
     * Records, for each child/parent pair, that the parent is the child's Parent.
     *
     * Only the child -> parent record is inserted (Contact = child, RelatedContact = parent,
     * Type = Parent). With the List Setting reciprocal method, NPSP's relationship trigger
     * creates the single reciprocal record (parent -> child) itself. It picks Son, Daughter
     * or Child from the Relationship Lookup using the child's gender, and links the two
     * records through npe4__ReciprocalRelationship__c. Inserting the reverse record here
     * as well would produce duplicates.
     */
    public static void linkParents(Map<Id, Id> parentIdByChildId) {
        if (parentIdByChildId == null || parentIdByChildId.isEmpty()) {
            return;
        }

        // Collect valid pairs and all contact ids involved
        Set<Id> contactIds = new Set<Id>();
        for (Id childId : parentIdByChildId.keySet()) {
            Id parentId = parentIdByChildId.get(childId);
            if (childId == null || parentId == null || childId == parentId) {
                continue;
            }
            contactIds.add(childId);
            contactIds.add(parentId);
        }
        if (contactIds.isEmpty()) {
            return;
        }

        // Single query: any existing relationship between contacts in the set, in either direction
        Set<String> existingPairs = new Set<String>();
        for (npe4__Relationship__c rel : [
            SELECT npe4__Contact__c, npe4__RelatedContact__c
            FROM npe4__Relationship__c
            WHERE npe4__Contact__c IN :contactIds
            AND npe4__RelatedContact__c IN :contactIds
            WITH USER_MODE
        ]) {
            existingPairs.add(pairKey(rel.npe4__Contact__c, rel.npe4__RelatedContact__c));
        }

        List<npe4__Relationship__c> toInsert = new List<npe4__Relationship__c>();
        for (Id childId : parentIdByChildId.keySet()) {
            Id parentId = parentIdByChildId.get(childId);
            if (childId == null || parentId == null || childId == parentId) {
                continue;
            }
            String key = pairKey(childId, parentId);
            if (existingPairs.contains(key)) {
                continue;
            }
            // Also guards against the same pair appearing twice (e.g. reversed) in the input
            existingPairs.add(key);

            toInsert.add(new npe4__Relationship__c(
                npe4__Contact__c = childId,
                npe4__RelatedContact__c = parentId,
                npe4__Type__c = PARENT_TYPE,
                npe4__Status__c = CURRENT_STATUS
            ));
        }

        if (!toInsert.isEmpty()) {
            insert as user toInsert;
        }
    }

    // Direction-independent key for a pair of contacts
    private static String pairKey(Id a, Id b) {
        String sa = String.valueOf(a);
        String sb = String.valueOf(b);
        return sa < sb ? sa + '|' + sb : sb + '|' + sa;
    }
}
