      "package": "Case Triage",
      "versionName": "Version 1.2.0",
      "versionNumber": "1.2.0.NEXT",
      "ancestorVersion": "HIGHEST",
      "unpackagedMetadata": {
        "path": "triage-test-fixtures"
      },
      "apexTestAccess": {
        "permissionSets": [
          "Triage_Agent"
        ],
        "permissionSetLicenses": [
          "SalesConsoleUser"
        ]
      }
    },
    {
      "path": "triage-test-fixtures",
