public with sharing class ContactImportService {
    private static final String WELCOME_TASK_ACTION = 'TA_Contact_CreateWelcomeTask';

    public static void importContacts(List<Contact> contacts) {
        if (contacts == null || contacts.isEmpty()) {
            return;
        }

        // Only clear the bypass afterwards if this method was the one that set it,
        // so a bypass already established by a caller is not removed unexpectedly.
        Boolean alreadyBypassed = MetadataTriggerHandler.isBypassed(WELCOME_TASK_ACTION);
        if (!alreadyBypassed) {
            MetadataTriggerHandler.bypass(WELCOME_TASK_ACTION);
        }

        try {
            // Single DML statement; TA_Contact_FormatPhone and all other
            // Contact automation still run.
            insert contacts;
        } finally {
            if (!alreadyBypassed) {
                MetadataTriggerHandler.clearBypass(WELCOME_TASK_ACTION);
            }
        }
    }
}
