    }

    @IsTest
    static void reductionOfMoreThanHalfIsRejected() {
        Id oppId = TriggerTestUtility.getFakeId(Schema.Opportunity.SObjectType);
        List<Opportunity> oldList = new List<Opportunity>{ newOpp(oppId, 1000) };
        List<Opportunity> newList = new List<Opportunity>{ newOpp(oppId, 499) };

        new TA_Opportunity_GuardAmountDecrease().beforeUpdate(newList, oldList);

        assertSingleError(newList[0], '1000 -> 499');
    }

