        List<Opportunity> newList = new List<Opportunity>{ newOpp(oppId, 1500) };

        new TA_Opportunity_GuardAmountDecrease().beforeUpdate(newList, oldList);

        assertNoError(newList[0], '1000 -> 1500');
    }

