/**
 * Trigger action (Trigger Actions Framework) that prevents two Contacts of the same Account
 * from sharing an email address (case-insensitive).
 *
 * - Contacts without Account or without Email are ignored.
 * - On update only contacts whose Email or AccountId changed are checked.
 * - Within one save the first contact in the list wins, later ones are rejected.
 * - At most one SOQL query per execution.
 *
 * "without sharing": the rule must hold regardless of which contacts the running user can see.
 * No record data is exposed, only a fixed error message.
 */
public without sharing class TA_Contact_PreventDuplicateEmail implements TriggerAction.BeforeInsert, TriggerAction.BeforeUpdate {
    @TestVisible
    private static final String ERROR_MESSAGE = 'Another contact on this account already uses this email address.';

    public void beforeInsert(List<SObject> triggerNew) {
        check((List<Contact>) triggerNew, null);
    }

    public void beforeUpdate(List<SObject> triggerNew, List<SObject> triggerOld) {
        Map<Id, Contact> oldById = new Map<Id, Contact>();
        for (SObject so : triggerOld) {
            Contact c = (Contact) so;
            oldById.set(c.Id, c);
        }
        check((List<Contact>) triggerNew, oldById);
    }

    private void check(List<Contact> newContacts, Map<Id, Contact> oldById) {
        Boolean isUpdate = oldById != null;

        // Keys already taken by contacts of this save that are NOT being checked (unchanged on update)
        Set<String> occupiedKeys = new Set<String>();
        // Contacts that must be validated, in list order
        List<Contact> toCheck = new List<Contact>();
        Set<Id> accountIds = new Set<Id>();
        Set<String> emails = new Set<String>();
        Set<Id> batchIds = new Set<Id>();

        for (Contact c : newContacts) {
            if (c.Id != null) {
                batchIds.add(c.Id);
            }
            String key = buildKey(c.AccountId, c.Email);
            if (key == null) {
                continue;
            }
            Boolean needsCheck = true;
            if (isUpdate) {
                Contact old = oldById.get(c.Id);
                if (old != null && key == buildKey(old.AccountId, old.Email)) {
                    needsCheck = false;
                }
            }
            if (needsCheck) {
                toCheck.add(c);
                accountIds.add(c.AccountId);
                emails.add(normalize(c.Email));
            } else {
                occupiedKeys.add(key);
            }
        }

        if (toCheck.isEmpty()) {
            return;
        }

        // One query. Contacts in this save are excluded because the database still holds their old
        // values; their new values are handled in memory. SOQL string comparison is case-insensitive.
        for (Contact existing : [
            SELECT AccountId, Email
            FROM Contact
            WHERE AccountId IN :accountIds AND Email IN :emails AND Id NOT IN :batchIds
            WITH SYSTEM_MODE
        ]) {
            String key = buildKey(existing.AccountId, existing.Email);
            if (key != null) {
                occupiedKeys.add(key);
            }
        }

        for (Contact c : toCheck) {
            String key = buildKey(c.AccountId, c.Email);
            if (occupiedKeys.contains(key)) {
                c.addError(ERROR_MESSAGE);
            } else {
                occupiedKeys.add(key);
            }
        }
    }

    private static String normalize(String email) {
        return email == null ? null : email.trim().toLowerCase();
    }

    private static String buildKey(Id accountId, String email) {
        String normalized = normalize(email);
        if (accountId == null || String.isBlank(normalized)) {
            return null;
        }
        return String.valueOf(accountId) + '|' + normalized;
    }
}
