```apex
/**
 * Keeps Account.FB_Open_Case_Count__c equal to the number of the account's Cases
 * with IsClosed = false. Registered for after insert, after update, after delete
 * and after undelete on Case through Trigger_Action__mdt.
 *
 * Runs without sharing on purpose: the count must be the true total and must be
 * written regardless of the running user's record access.
 */
public without sharing class TA_Case_RollupOpenCount implements TriggerAction.AfterInsert, TriggerAction.AfterUpdate, TriggerAction.AfterDelete, TriggerAction.AfterUndelete {
    public void afterInsert(List<SObject> triggerNew) {
        Set<Id> accountIds = new Set<Id>();
        for (SObject so : triggerNew) {
            addAccountId(accountIds, (Case) so);
        }
        recalculate(accountIds);
    }

    public void afterUpdate(List<SObject> triggerNew, List<SObject> triggerOld) {
        Set<Id> accountIds = new Set<Id>();
        for (Integer i = 0; i < triggerNew.size(); i++) {
            Case newCase = (Case) triggerNew[i];
            Case oldCase = (Case) triggerOld[i];
            if (newCase.AccountId != oldCase.AccountId || newCase.IsClosed != oldCase.IsClosed) {
                addAccountId(accountIds, newCase);
                addAccountId(accountIds, oldCase);
            }
        }
        recalculate(accountIds);
    }

    public void afterDelete(List<SObject> triggerOld) {
        Set<Id> accountIds = new Set<Id>();
        for (SObject so : triggerOld) {
            addAccountId(accountIds, (Case) so);
        }
        recalculate(accountIds);
    }

    public void afterUndelete(List<SObject> triggerNew) {
        Set<Id> accountIds = new Set<Id>();
        for (SObject so : triggerNew) {
            addAccountId(accountIds, (Case) so);
        }
        recalculate(accountIds);
    }

    private static void addAccountId(Set<Id> accountIds, Case c) {
        if (c.AccountId != null) {
            accountIds.add(c.AccountId);
        }
    }

    private static void recalculate(Set<Id> accountIds) {
        if (accountIds.isEmpty()) {
            return;
        }

        // Accounts without any open case are absent from the aggregate result: default to 0.
        Map<Id, Integer> openCounts = new Map<Id, Integer>();
        for (Id accountId : accountIds) {
            openCounts.put(accountId, 0);
        }

        for (AggregateResult ar : [
            SELECT AccountId accId, COUNT(Id) cnt
            FROM Case
            WHERE AccountId IN :accountIds AND IsClosed = false
            GROUP BY AccountId
        ]) {
            openCounts.put((Id) ar.get('accId'), Integer.valueOf(ar.get('cnt')));
        }

        List<Account> accountsToUpdate = new List<Account>();
        for (Id accountId : openCounts.keySet()) {
            accountsToUpdate.add(new Account(Id = accountId, FB_Open_Case_Count__c = openCounts.get(accountId)));
        }
        update accountsToUpdate;
    }
}
```

